local pm=r:GetProjectManager() local p=pm:GetCurrentProject() assert(p:GetName()=="VEL_Weekender_Haaland_20260912") assert(not p:IsRenderingInProgress()) local t=p:GetCurrentTimeline() assert(t:GetName()=="Weekender-Haaland-Natural-AvatarV-v2") assert(pm:SaveProject()) local n="Weekender-Haaland-Natural-AvatarV-v3-EndSync" for i=1,p:GetTimelineCount() do assert(p:GetTimelineByIndex(i):GetName()~=n,"Revision already exists") end local nt=t:DuplicateTimeline(n) assert(nt) assert(p:SetCurrentTimeline(nt)) local bg=nt:GetItemListInTrack("video",1) local last=bg[#bg] assert(last:GetStart()==1214 and last:GetEnd()==1371) local media=last:GetMediaPoolItem() local props=last:GetProperty() assert(nt:DeleteClips({last},false)) local added=p:GetMediaPool():AppendToTimeline({{mediaPoolItem=media,startFrame=0,endFrame=96,recordFrame=1214,trackIndex=1,mediaType=1}}) assert(added and #added==1) added[1]:SetProperties(props) assert(added[1]:GetStart()==1214 and added[1]:GetEnd()==1311) local markers=nt:GetMarkers() local m=markers[1214] if m then assert(nt:DeleteMarkerAtFrame(1214)) assert(nt:AddMarker(1214,m.color,m.name,"Clean bag hero; full CTA. End with narration; no extra end hold.",97,m.customData)) end assert(nt:GetEndFrame()==1311) assert(nt:GetItemListInTrack("audio",1)[1]:GetEnd()==1311) assert(pm:SaveProject()) r:OpenPage("edit") return {project=p:GetName(),timeline=nt:GetName(),preserved=t:GetName(),picture_end=nt:GetEndFrame(),audio_end=nt:GetItemListInTrack("audio",1)[1]:GetEnd(),last_duration=added[1]:GetDuration()}